     ///
     /// # Parameters
     ///
     /// - `alignment`: The alignment to align the target address to.
     ///
     /// # Returns
     ///
     /// Upon success, the aligned address is returned. Upon failure, an error is returned instead.
     ///
     fn align_up(&self, align: Alignment) -> Result<Self, Error>;

